import {CITIES,CITY,PROJECTS} from './data.js';
import {COUNTRIES} from './assets/geography.js';
import {REAL_STATIONS} from './assets/realdata.js';
import {RAILWAYS,RAIL_PATHS} from './assets/railways.js';
import {isUnlocked,routeName} from './engine.js';
import {daylight,constructionStatus} from './operations.js';
export class RailMap {
 constructor(canvas,getState,onSelect,getOperations){Object.assign(this,{canvas,ctx:canvas.getContext('2d'),getState,onSelect,getOperations,zoom:1,pan:{x:0,y:0},layer:'network',selected:null,hover:null,points:[],dirty:true,lastFrame:0,pointers:new Map()});this.cache=document.createElement('canvas');new ResizeObserver(()=>this.resize()).observe(canvas);
 canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoomAt(this.zoom*(e.deltaY<0?1.18:.85),e.offsetX,e.offsetY);},{passive:false});
 canvas.addEventListener('pointerdown',e=>{const p=this.local(e);this.pointers.set(e.pointerId,p);canvas.setPointerCapture(e.pointerId);this.drag={id:e.pointerId,x:p[0],y:p[1],px:this.pan.x,py:this.pan.y,moved:false};if(this.pointers.size===2)this.pinch={distance:this.pointerDistance(),zoom:this.zoom};});
 canvas.addEventListener('pointermove',e=>{const p=this.local(e);if(this.pointers.has(e.pointerId))this.pointers.set(e.pointerId,p);if(this.pointers.size===2&&this.pinch){this.zoomAt(this.pinch.zoom*this.pointerDistance()/this.pinch.distance);this.drag.moved=true;}else if(this.drag?.id===e.pointerId){const dx=p[0]-this.drag.x,dy=p[1]-this.drag.y;this.drag.moved||=Math.hypot(dx,dy)>4;this.pan.x=this.drag.px+dx;this.pan.y=this.drag.py+dy;this.dirty=true;}else this.hover=this.hit(...p);canvas.style.cursor=this.drag?'grabbing':this.hover?'pointer':'grab';});
 canvas.addEventListener('pointerup',e=>{if(this.drag&&!this.drag.moved&&this.pointers.size===1){const id=this.hit(...this.local(e));if(id)this.onSelect(id);}this.pointers.delete(e.pointerId);this.drag=null;this.pinch=null;});canvas.addEventListener('pointercancel',e=>{this.pointers.delete(e.pointerId);this.drag=null;this.pinch=null;});requestAnimationFrame(t=>this.render(t));}
 local(e){const r=this.canvas.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];}
 pointerDistance(){const p=[...this.pointers.values()];return Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);}
 resize(){const r=this.canvas.getBoundingClientRect();this.w=r.width;this.h=r.height;this.dpr=Math.min(devicePixelRatio||1,2);this.canvas.width=this.cache.width=this.w*this.dpr;this.canvas.height=this.cache.height=this.h*this.dpr;this.dirty=true;}
 zoomAt(z,x=this.w/2,y=this.h/2){const before=this.zoom;this.zoom=Math.max(.7,Math.min(35,z));this.pan.x=x-this.w/2-(x-this.w/2-this.pan.x)*this.zoom/before;this.pan.y=y-this.h/2-(y-this.h/2-this.pan.y)*this.zoom/before;this.dirty=true;}
 project(lon,lat){const base=Math.min((this.w-50)/13.8,(this.h-150)/10.8)*this.zoom;return [(lon+3.4)*base+this.w*.49+this.pan.x,(40.2-lat)*base*1.29+this.h*.48+this.pan.y];}
 reset(){this.zoom=1;this.pan={x:0,y:0};this.selected=null;this.dirty=true;}
 focus(id,zoom=false){this.selected=id;const r=this.getState().routes.find(r=>r.id===id);if(r&&zoom){const a=CITY[r.ends[0]],b=CITY[r.ends[1]];this.focusAt((a.lon+b.lon)/2,(a.lat+b.lat)/2,Math.min(20,Math.max(2.5,8/Math.max(.4,Math.abs(a.lon-b.lon),Math.abs(a.lat-b.lat)*1.3))));}this.dirty=true;}
 focusAt(lon,lat,z=10){this.zoom=z;this.pan={x:0,y:0};const p=this.project(lon,lat);this.pan={x:this.w*.42-p[0],y:this.h*.48-p[1]};this.dirty=true;}
 coordinates(r){const asset=RAIL_PATHS[r.id];return asset?(asset.coordinates||asset):r.custom?r.via.map(id=>[CITY[id].lon,CITY[id].lat]):[];}
 hit(x,y){let best=null,distance=10;for(const r of this.points)for(let i=1;i<r.points.length;i++){const a=r.points[i-1],b=r.points[i],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1))),d=Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy);if(d<distance){distance=d;best=r.id;}}return best;}
 drawBase(){const c=this.cache.getContext('2d'),w=this.w,h=this.h;c.setTransform(this.dpr,0,0,this.dpr,0,0);c.fillStyle='#8eb8be';c.fillRect(0,0,w,h);for(const f of COUNTRIES){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;for(const rings of polys){c.beginPath();for(const coords of rings){coords.forEach(([lon,lat],i)=>{const p=this.project(lon,lat);i?c.lineTo(...p):c.moveTo(...p);});c.closePath();}c.fillStyle=f.id==='ESP'?'#d7d2ab':f.id==='PRT'?'#bec7a4':'#c4cbb3';c.fill('evenodd');c.strokeStyle='#667d7040';c.lineWidth=1;c.stroke();}}
 c.lineWidth=this.zoom>4?1.6:.65;c.strokeStyle='#82765c60';c.beginPath();for(const segment of RAILWAYS){const coords=segment.c||segment.coordinates||segment.geometry?.coordinates;if(!coords?.length)continue;const a=this.project(...coords[0]),b=this.project(...coords.at(-1));if((a[0]<-100&&b[0]<-100)||(a[0]>w+100&&b[0]>w+100)||(a[1]<-100&&b[1]<-100)||(a[1]>h+100&&b[1]>h+100))continue;coords.forEach((p,i)=>{const q=this.project(...p);i?c.lineTo(...q):c.moveTo(...q);});}c.stroke();c.font='13px Georgia';c.fillStyle='#526f7466';c.textAlign='center';for(const [name,lon,lat] of [['PORTUGAL',-8,39.5],['FRANCIA',1.2,44],['MAR MEDITERRÁNEO',1.3,37.6],['ATLÁNTICO',-10.1,40.4]])c.fillText(name,...this.project(lon,lat));this.points=this.getState().routes.map(r=>({id:r.id,points:this.coordinates(r).map(p=>this.project(...p)),real:!!RAIL_PATHS[r.id]}));this.dirty=false;}
 pointOn(points,ratio){const lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));let d=lengths.reduce((a,b)=>a+b,0)*Math.max(0,Math.min(1,ratio)),i=0;while(i<lengths.length-1&&d>lengths[i]){d-=lengths[i];i++;}const a=points[i],b=points[i+1]||a,f=d/(lengths[i]||1);return {x:a[0]+(b[0]-a[0])*f,y:a[1]+(b[1]-a[1])*f,angle:Math.atan2(b[1]-a[1],b[0]-a[0])};}
 render(t){requestAnimationFrame(t=>this.render(t));if(!this.w||t-this.lastFrame<40||document.hidden)return;this.lastFrame=t;if(this.dirty)this.drawBase();const c=this.ctx,s=this.getState(),op=this.getOperations(),w=this.w,h=this.h,light=daylight(s,op.minute??840);c.setTransform(this.dpr,0,0,this.dpr,0,0);c.drawImage(this.cache,0,0,w,h);c.fillStyle=`rgba(17,25,54,${light.night*.76})`;c.fillRect(0,0,w,h);
 for(const line of this.points){if(line.points.length<2)continue;const r=s.routes.find(r=>r.id===line.id),selected=r.id===this.selected||r.id===this.hover,works=!isUnlocked(s,r)||s.projects.some(p=>!p.done&&(p.route===r.id||PROJECTS.find(d=>d.id===p.id)?.routes.includes(r.id)));if(this.layer==='works'&&!works&&!selected)continue;c.beginPath();line.points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.setLineDash(!line.real||r.custom?[3,6]:works?[8,5]:[]);c.strokeStyle=selected?'#fff0b4':works?'#d89637':r.active?(light.night>.5?'#b4ded0':'#863551'):'#857e6755';c.lineWidth=selected?4:r.active?2.5:1;c.lineJoin='round';c.lineCap='round';c.stroke();c.setLineDash([]);if(works){const job=s.projects.find(p=>!p.done&&(p.route===r.id||PROJECTS.find(d=>d.id===p.id)?.routes.includes(r.id)));if(job){const progress=constructionStatus(s,job).progress,p=this.pointOn(line.points,progress);c.fillStyle='#ffc664';c.beginPath();c.arc(p.x,p.y,selected?6:4,0,Math.PI*2);c.fill();}}}
 const major=new Set(['mad','bcn','vlc','ali','mur','alm','gra','mal','sev','cor','zar','bil','don','san','bur','vll','leo','ovi','aco','scq','vig','our','sal','bad','cac','car','ter']);for(const city of CITIES){const p=this.project(city.lon,city.lat);if(p[0]<0||p[0]>w||p[1]<0||p[1]>h)continue;const important=major.has(city.id);if(light.night>.1){c.fillStyle=`rgba(255,197,94,${light.night*.72})`;c.shadowColor='#ffd578';c.shadowBlur=8;for(let j=0;j<(important?12:5);j++){const a=j*2.399,rad=Math.sqrt(j)*2.7;c.beginPath();c.arc(p[0]+Math.cos(a)*rad,p[1]+Math.sin(a)*rad,1.1,0,Math.PI*2);c.fill();}c.shadowBlur=0;}if(!important&&this.zoom<2)continue;c.fillStyle=light.night>.5?'#fff4bf':'#74424e';c.beginPath();c.arc(...p,city.id==='mad'?4:2.5,0,Math.PI*2);c.fill();c.font="500 13px 'Segoe UI',sans-serif";c.textAlign='left';c.lineWidth=3;c.strokeStyle=light.night>.5?'#1b263acc':'#d7d2abb0';c.strokeText(city.name,p[0]+7,p[1]-7);c.fillStyle=light.night>.5?'#f9ead1':'#353b32';c.fillText(city.name,p[0]+7,p[1]-7);}
 if(this.zoom>3)for(const station of REAL_STATIONS){const p=this.project(station.lon,station.lat);if(p[0]<5||p[0]>w-5||p[1]<5||p[1]>h-5)continue;c.fillStyle=light.night>.5?'#efc887':'#6a5358';c.beginPath();c.arc(...p,1.6,0,Math.PI*2);c.fill();if(this.zoom>10){c.font='12px Segoe UI';c.fillText(station.name,p[0]+5,p[1]+12);}}
 for(const trip of op.trips||[]){if(trip.approximate||trip.arrival===null)continue;if(op.minute<trip.dep||op.minute>=trip.arrival)continue;let pts=this.points.find(p=>p.id===trip.route)?.points;if(trip.real||!pts)pts=trip.coords.map(p=>this.project(...p));if(!pts?.length)continue;let ratio=(op.minute-trip.dep)/(trip.arrival-trip.dep||1);if(trip.direction&&!trip.real)ratio=1-ratio;const p=this.pointOn(pts,ratio);if(p.x<0||p.x>w||p.y<0||p.y>h)continue;c.save();c.translate(p.x,p.y);c.rotate(p.angle+(trip.direction&&!trip.real?Math.PI:0));if(light.night>.4){c.fillStyle='#ffed9b33';c.beginPath();c.moveTo(5,0);c.lineTo(22,-8);c.lineTo(22,8);c.fill();}c.fillStyle='#fff6e3';c.strokeStyle=trip.real?trip.color:'#943757';c.lineWidth=1.6;c.beginPath();c.roundRect(-8,-3,17,6,2);c.fill();c.stroke();c.fillStyle='#e2b949';c.fillRect(5,-2,2,4);c.restore();}
 if(this.hover){const r=s.routes.find(r=>r.id===this.hover);if(r){const line=this.points.find(p=>p.id===r.id),p=this.pointOn(line.points,.5);c.font='14px Segoe UI';const name=routeName(r),width=c.measureText(name).width;c.fillStyle='#faf1dcf0';c.fillRect(p.x-width/2-9,p.y+12,width+18,29);c.fillStyle='#493838';c.textAlign='center';c.fillText(name,p.x,p.y+32);}}
 }
}
